declare(strict_types=1);

namespace DmLab\TypesenseCore\Model\Collection;

use DmLab\TypesenseCore\Exception\TypesenseException;
use Magento\Framework\Stdlib\DateTime\DateTime;

/**
 * Versioned collections no alias points to — the leftovers of a rebuild killed before its swap.
 *
 * Only collections of a still-existing alias qualify: without the alias nothing proves the
 * collection was generated by {@see AliasManager::generateCollectionName()}.
 */
class OrphanFinder
{
    private const VERSIONED_NAME = '/^(?<alias>.+)_(?<ts>\d{10})_(?<hex>[0-9a-f]{6})$/';

    /**
     * @param CollectionManager $collections
     * @param AliasManager $aliases
     * @param DateTime $dateTime
     * @param AliasLock $lock
     */
    public function __construct(
        private readonly CollectionManager $collections,
        private readonly AliasManager $aliases,
        private readonly DateTime $dateTime,
        private readonly AliasLock $lock
    ) {
    }

    /**
     * Orphaned collection names, sorted.
     *
     * @param int $minAgeSeconds a running rebuild's collection stays unaliased until its swap
     * @return string[]
     * @throws TypesenseException
     */
    public function find(int $minAgeSeconds): array
    {
        // Collections before aliases: a swap landing in between then shows its new target as aliased.
        $collections = $this->collections->getList();
        $aliases = $this->aliases->getList();
        $targets = array_flip(array_values($aliases));
        $now = (int)$this->dateTime->gmtTimestamp();

        $orphans = [];
        foreach ($collections as $name) {
            if (isset($targets[$name]) || !preg_match(self::VERSIONED_NAME, $name, $match)) {
                continue;
            }
            if (!array_key_exists($match['alias'], $aliases)) {
                continue;
            }
            if ($now - (int)$match['ts'] >= $minAgeSeconds) {
                $orphans[] = $name;
            }
        }

        return $orphans;
    }

    /**
     * Drop a listed orphan unless an alias points at it now.
     *
     * The recheck and the drop hold the alias's {@see AliasLock}, the one {@see AliasManager::swap()} takes,
     * so a swap cannot alias the collection in between.
     *
     * @param string $collection
     * @return bool false when skipped because it is aliased or not a versioned name
     * @throws TypesenseException 404 when the collection is already gone
     */
    public function drop(string $collection): bool
    {
        if (!preg_match(self::VERSIONED_NAME, $collection, $match)) {
            return false;
        }

        return $this->lock->synchronized($match['alias'], function () use ($collection): bool {
            if (in_array($collection, $this->aliases->getList(), true)) {
                return false;
            }
            $this->collections->drop($collection);

            return true;
        });
    }
}
